//
// test_v5.c — HOST test bench of protocol v5 (MONITOR), ESP32 side.
//
// Compiles and links the REAL module (src/monitor.c) and protocol_v5.h against
// the vectors generated by tools/check_v5.py (--c), which derives them from an
// independent Python implementation written from the specification: what is
// verified is the code that runs on the device.
//
//   cd esp32/main/test
//   gcc -I stub -I ../include -Wall -Wextra test_v5.c ../src/monitor.c -o test_v5 && ./test_v5
//
// Covers:
//   1. the alert builder against the vectors, byte for byte;
//   2. the edge cases of the builder: empty, NULL or too long text, reserved
//      bits of alert, CRC-8 that closes;
//   3. alert numbering: 1..255, then 1 again, never 0;
//   4. the uplink parser: every field of every vector, including ev_ack,
//      ev_user and the confirmations-only packet (n_samples = 0);
//   5. rejection of invalid packets: magic, version (including v4's 0x05 with
//      a correct CRC), n_samples above 8, wrong lengths, and EVERY single-bit
//      corruption in EVERY position;
//   6. per-node continuity: new session, duplicates, jumps, session change,
//      and confirmations-only packets that do not affect it;
//   7. the text values for CSV and console: batt, alt, sentinels.
//
// WHAT THIS TEST CANNOT PROVE: alert validation and duplicates, which live on
// the watch (V5_BAD_ALERTS lists the cases), the routing of 0x06 (proved in
// test_v4.c, with the v4 parser), SD writing and the radio behaviour: write
// response, ALERT subscription, notification, THIS_EDGE_EVENT_S cycle.
//
#include <stdio.h>
#include <string.h>

#include "monitor.h"
#include "v5_vectors.h"

static int failures = 0;

#define CHECK(cond, ...) do {                      \
    if (!(cond)) {                                 \
        printf("  [FAIL] " __VA_ARGS__);           \
        printf("\n");                              \
        failures++;                                \
    }                                              \
} while (0)

static void hex(const uint8_t *b, int n) {
    for (int i = 0; i < n; i++) { printf("%02X", b[i]); }
}

// ---------------------------------------------------------------------------
// 1. Alert builder against the vectors
// ---------------------------------------------------------------------------
static void test_alerts(void) {
    printf("[1] Alerts: builder against the vectors\n");
    for (int i = 0; i < V5_ALERTS_N; i++) {
        const v5_alert_t *x = &V5_ALERTS[i];
        uint8_t out[V5_ALERT_BYTES];
        v5_build_alert(x->node_id, x->ev_seq, x->ev_type, x->alert, x->ev_value, x->text, out);
        if (memcmp(out, x->bytes, V5_ALERT_BYTES) != 0) {
            printf("  [FAIL] %s:\n         got      ", x->name);
            hex(out, V5_ALERT_BYTES);
            printf("\n         expected ");
            hex(x->bytes, V5_ALERT_BYTES);
            printf("\n");
            failures++;
        }
    }
    printf("    %d alerts examined\n", V5_ALERTS_N);
}

// ---------------------------------------------------------------------------
// 2. Edge cases of the builder
// ---------------------------------------------------------------------------
static void test_alert_edges(void) {
    printf("[2] Alerts: edge cases of the builder\n");
    uint8_t a[V5_ALERT_BYTES], b[V5_ALERT_BYTES];

    // NULL and empty text give the same alert: 11 bytes at 0.
    v5_build_alert(2, 1, V5_EV_TEST, 0, 0, NULL, a);
    v5_build_alert(2, 1, V5_EV_TEST, 0, 0, "", b);
    CHECK(memcmp(a, b, V5_ALERT_BYTES) == 0, "NULL text differs from empty text");
    for (int i = 0; i < V5_TEXT_BYTES; i++) {
        CHECK(a[V5_A_TEXT + i] == 0, "empty text: byte %d = 0x%02X", i, a[V5_A_TEXT + i]);
    }

    // Text longer than 11 bytes: truncated, and the CRC stays in its byte.
    v5_build_alert(2, 1, V5_EV_TEST, 0, 0, "ABCDEFGHIJKLMNOP", a);
    CHECK(memcmp(a + V5_A_TEXT, "ABCDEFGHIJK", V5_TEXT_BYTES) == 0, "long text not truncated to 11");
    CHECK(a[V5_A_CRC8] == v3_crc8(a, V5_A_CRC8), "long text: CRC-8 overwritten");

    // Bits 2-7 of alert are reserved: they are cleared.
    v5_build_alert(2, 1, V5_EV_TEST, 0xFF, 0, "x", a);
    CHECK(a[V5_A_ALERT] == (V5_AL_VIBE | V5_AL_TONE), "alert 0xFF -> 0x%02X, expected 0x03",
          a[V5_A_ALERT]);

    // The simulated alert of ble.c (ev_value = 0): fields and CRC in place.
    v5_build_alert(2, 3, V5_EV_TEST, V5_AL_TONE, 0, "E2 #3", a);
    CHECK(a[V5_A_MAGIC] == 0x5A && a[V5_A_VER] == 0x06 && a[V5_A_NODE] == 2 &&
          a[V5_A_SEQ] == 3 && a[V5_A_TYPE] == 0 && a[V5_A_ALERT] == V5_AL_TONE,
          "simulated alert: wrong header");
    CHECK(a[V5_A_VALUE] == 0 && a[V5_A_VALUE + 1] == 0, "simulated alert: ev_value != 0");
    CHECK(memcmp(a + V5_A_TEXT, "E2 #3\0\0\0\0\0\0", V5_TEXT_BYTES) == 0,
          "simulated alert: wrong text");
    CHECK(a[V5_A_CRC8] == v3_crc8(a, V5_A_CRC8), "simulated alert: CRC-8 does not close");

    CHECK(v3_crc8((const uint8_t *)"123456789", 9) == 0xF4, "crc8('123456789') != 0xF4");
}

// ---------------------------------------------------------------------------
// 3. Alert numbering
// ---------------------------------------------------------------------------
static void test_ev_seq(void) {
    printf("[3] Alert numbering\n");
    CHECK(v5_next_ev_seq(0) == 1, "0 -> %u, expected 1", v5_next_ev_seq(0));
    CHECK(v5_next_ev_seq(1) == 2, "1 -> %u, expected 2", v5_next_ev_seq(1));
    CHECK(v5_next_ev_seq(254) == 255, "254 -> %u, expected 255", v5_next_ev_seq(254));
    CHECK(v5_next_ev_seq(255) == 1, "255 -> %u, expected 1", v5_next_ev_seq(255));

    // Three full rounds from boot (s_alert_seq = 0): never 0, always +1 or 255 -> 1.
    uint8_t s = 0;
    for (int i = 0; i < 3 * 255; i++) {
        uint8_t n = v5_next_ev_seq(s);
        CHECK(n != 0, "step %d: ev_seq 0 after %u", i, s);
        CHECK(n == (s == 255 ? 1 : s + 1), "step %d: %u -> %u", i, s, n);
        s = n;
    }
}

// ---------------------------------------------------------------------------
// 4. Uplink parser against the vectors
// ---------------------------------------------------------------------------
static void test_parse(void) {
    printf("[4] Uplink: parsing the vectors\n");
    for (int i = 0; i < V5_PACKETS_N; i++) {
        const v5_vec_t *v = &V5_PACKETS[i];
        monitor_pkt_t p;

        CHECK(v->len == v5_expected_len(v->n_samples), "%s: len %lu != expected %lu", v->name,
              (unsigned long)v->len, (unsigned long)v5_expected_len(v->n_samples));
        CHECK(v->len <= V5_MAX_PKT_BYTES, "%s: len %lu above the maximum", v->name,
              (unsigned long)v->len);

        monitor_result_t r = monitor_parse(v->bytes, v->len, &p);
        if (r != MONITOR_OK) {
            printf("  [FAIL] %s: valid packet REJECTED (%s)\n",
                   v->name, monitor_result_name(r));
            failures++;
            continue;
        }

        CHECK(p.node_id == v->node_id, "%s: node %u != %u", v->name, p.node_id, v->node_id);
        CHECK(p.n_samples == v->n_samples, "%s: n %u != %u", v->name, p.n_samples, v->n_samples);
        CHECK(p.session_id == v->session_id, "%s: session %lu != %lu", v->name,
              (unsigned long)p.session_id, (unsigned long)v->session_id);
        CHECK(p.seq_first == v->seq_first, "%s: seq %lu != %lu", v->name,
              (unsigned long)p.seq_first, (unsigned long)v->seq_first);
        CHECK(p.backlog == v->backlog, "%s: backlog %u != %u", v->name, p.backlog, v->backlog);
        CHECK(p.conn_no == v->conn_no, "%s: conn_no %u != %u", v->name, p.conn_no, v->conn_no);
        CHECK(p.ev_ack == v->ev_ack, "%s: ev_ack %u != %u", v->name, p.ev_ack, v->ev_ack);
        CHECK(p.ev_user == v->ev_user, "%s: ev_user %u != %u", v->name, p.ev_user, v->ev_user);

        for (uint8_t s = 0; s < v->n_samples; s++) {
            const monitor_sample_t *x = &p.s[s];
            CHECK(x->real_time == v->real_time[s], "%s[%u]: realTime %lu != %lu", v->name, s,
                  (unsigned long)x->real_time, (unsigned long)v->real_time[s]);
            CHECK(x->hr == v->value[s][0], "%s[%u]: hr %u != %u", v->name, s, x->hr, v->value[s][0]);
            CHECK(x->batt == v->value[s][1], "%s[%u]: batt %u != %u", v->name, s, x->batt,
                  v->value[s][1]);
            CHECK(x->steps == v->value[s][2], "%s[%u]: steps %u != %u", v->name, s, x->steps,
                  v->value[s][2]);
            CHECK(x->alt == v->value[s][3], "%s[%u]: alt %u != %u", v->name, s, x->alt,
                  v->value[s][3]);
        }
    }
    printf("    %d packets examined\n", V5_PACKETS_N);
}

// ---------------------------------------------------------------------------
// 5. Rejection of invalid packets
// ---------------------------------------------------------------------------
static const v5_vec_t *vec(const char *name) {
    for (int i = 0; i < V5_PACKETS_N; i++) {
        if (strcmp(V5_PACKETS[i].name, name) == 0) { return &V5_PACKETS[i]; }
    }
    printf("  [FAIL] vector '%s' missing from v5_vectors.h\n", name);
    failures++;
    return &V5_PACKETS[0];
}

// Recomputes the CRC: the rejection must depend on the broken field, not on the CRC.
static void fix_crc(uint8_t *buf, uint32_t len) {
    uint16_t crc = v3_crc16(buf, len - V5_CRC_BYTES);
    buf[len - 2] = (uint8_t)(crc >> 8);
    buf[len - 1] = (uint8_t)crc;
}

static void test_reject(void) {
    printf("[5] Uplink: rejection of invalid packets\n");

    const v5_vec_t *v = vec("drain");         // 8 samples: the longest packet
    uint8_t buf[V5_MAX_PKT_BYTES + 2 * V5_SAMPLE_BYTES];
    monitor_pkt_t p;

    memcpy(buf, v->bytes, v->len);
    buf[V5_H_MAGIC] = 0x00;
    fix_crc(buf, v->len);
    CHECK(monitor_parse(buf, v->len, &p) == MONITOR_ERR_MAGIC, "wrong magic ACCEPTED");
    buf[V5_H_MAGIC] = V5_MAGIC_DOWN;          // the magic of the alert, not of the uplink
    fix_crc(buf, v->len);
    CHECK(monitor_parse(buf, v->len, &p) == MONITOR_ERR_MAGIC, "magic 0x5A ACCEPTED");

    // No other version may be read as v5 (same magic as v4).
    const uint8_t other_vers[] = { 0x03, 0x04, 0x05, 0x07, 0x00, 0xFF };
    for (unsigned i = 0; i < sizeof(other_vers); i++) {
        memcpy(buf, v->bytes, v->len);
        buf[V5_H_VER] = other_vers[i];
        fix_crc(buf, v->len);
        CHECK(monitor_parse(buf, v->len, &p) == MONITOR_ERR_MAGIC,
              "proto_ver 0x%02X ACCEPTED as v5", other_vers[i]);
    }

    // n_samples above 8, even with length and CRC consistent with that number:
    // the limit must decide, not the length.
    uint32_t len9 = v5_expected_len(V5_MAX_SAMPLES + 1);
    memcpy(buf, v->bytes, v->len - V5_CRC_BYTES);
    memcpy(buf + v->len - V5_CRC_BYTES, v->bytes + V5_HDR_BYTES, V5_SAMPLE_BYTES);
    buf[V5_H_NSAMPLES] = V5_MAX_SAMPLES + 1;
    fix_crc(buf, len9);
    CHECK(monitor_parse(buf, len9, &p) == MONITOR_ERR_NSAMPLES,
          "n_samples=9 with consistent length and CRC ACCEPTED");
    memcpy(buf, v->bytes, v->len);
    buf[V5_H_NSAMPLES] = 255;
    CHECK(monitor_parse(buf, v->len, &p) == MONITOR_ERR_NSAMPLES, "n_samples=255 ACCEPTED");

    // Wrong lengths.
    memcpy(buf, v->bytes, v->len);
    CHECK(monitor_parse(buf, v->len - 1, &p) == MONITOR_ERR_LEN, "truncated length ACCEPTED");
    buf[v->len] = 0x00;
    CHECK(monitor_parse(buf, v->len + 1, &p) == MONITOR_ERR_LEN, "extra byte ACCEPTED");
    CHECK(monitor_parse(buf, v5_expected_len(0) - 1, &p) == MONITOR_ERR_LEN,
          "17-byte packet ACCEPTED");
    CHECK(monitor_parse(buf, 1, &p) == MONITOR_ERR_LEN, "1-byte packet ACCEPTED");
    CHECK(monitor_parse(buf, 0, &p) == MONITOR_ERR_LEN, "empty packet ACCEPTED");

    // n_samples inconsistent with the bytes, in both directions.
    memcpy(buf, v->bytes, v->len);
    buf[V5_H_NSAMPLES] = 7;
    fix_crc(buf, v->len);
    CHECK(monitor_parse(buf, v->len, &p) == MONITOR_ERR_LEN, "n=7 with the bytes of 8 ACCEPTED");
    const v5_vec_t *r = vec("steady");          // 1 sample, 30 B
    memcpy(buf, r->bytes, r->len);
    buf[V5_H_NSAMPLES] = 0;
    fix_crc(buf, r->len);
    CHECK(monitor_parse(buf, r->len, &p) == MONITOR_ERR_LEN, "n=0 with the bytes of 1 ACCEPTED");
    const v5_vec_t *c = vec("confirmations");   // 0 samples, 18 B
    memcpy(buf, c->bytes, c->len);
    buf[V5_H_NSAMPLES] = 1;
    fix_crc(buf, c->len);
    CHECK(monitor_parse(buf, c->len, &p) == MONITOR_ERR_LEN, "n=1 with the bytes of 0 ACCEPTED");

    // Wrong CRC on an otherwise perfect packet.
    memcpy(buf, c->bytes, c->len);
    buf[c->len - 1] ^= 0x01;
    CHECK(monitor_parse(buf, c->len, &p) == MONITOR_ERR_CRC, "wrong CRC ACCEPTED");

    // Every bit of every vector, one at a time: no corruption may pass.
    int missed = 0;
    unsigned long total = 0;
    for (int i = 0; i < V5_PACKETS_N; i++) {
        const v5_vec_t *w = &V5_PACKETS[i];
        for (uint32_t pos = 0; pos < w->len; pos++) {
            for (int bit = 0; bit < 8; bit++) {
                memcpy(buf, w->bytes, w->len);
                buf[pos] ^= (uint8_t)(1u << bit);
                if (monitor_parse(buf, w->len, &p) == MONITOR_OK) { missed++; }
                total++;
            }
        }
    }
    CHECK(missed == 0, "%d single-bit corruptions NOT caught out of %lu", missed, total);
    printf("    %lu single-bit corruptions tried\n", total);
}

// ---------------------------------------------------------------------------
// 6. Per-node continuity
// ---------------------------------------------------------------------------
static monitor_pkt_t mk(uint32_t session, uint32_t seq, uint8_t n) {
    monitor_pkt_t p;
    memset(&p, 0, sizeof(p));
    p.session_id = session;
    p.seq_first  = seq;
    p.n_samples  = n;
    return p;
}

static bool quiet(const monitor_track_t *t) {
    return !t->new_session && !t->jump && t->first_new == 0;
}

static void test_track(void) {
    printf("[6] Uplink: duplicates and jumps per node\n");
    monitor_track_t t;
    monitor_pkt_t p;

    monitor_track_reset();

    // Confirmations only, before any sample (an alert confirmed before the
    // first sample arrives here): no session is opened.
    p = mk(0, 0, 0);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "confirmations before the samples: classified");

    // First packet: new session, even if it does not start from 0 (the watch
    // may have started on another edge).
    p = mk(1000, 40, 1);
    monitor_track(&p, &t);
    CHECK(t.new_session && !t.jump && t.first_new == 0, "first packet misclassified");

    // Confirmations only: seq_first is the next seq, and must not count.
    p = mk(1000, 41, 0);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "confirmations after 40: classified");

    // Regular next packet: the confirmations in between did not make it look
    // like a duplicate.
    p = mk(1000, 41, 1);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "41 after 40 and confirmations: misclassified");

    // Same packet retransmitted (write response lost): all duplicate.
    p = mk(1000, 41, 1);
    monitor_track(&p, &t);
    CHECK(t.first_new == 1 && !t.jump, "retransmission of 41: first_new %u != 1", t.first_new);

    // Partial overlap: 41..48 after receiving up to 41.
    p = mk(1000, 41, 8);
    monitor_track(&p, &t);
    CHECK(t.first_new == 1 && !t.jump, "41+8 after 41: first_new %u != 1", t.first_new);

    // Confirmations with a distant seq_first (or of another session): ignored.
    p = mk(1000, 500, 0);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "confirmations with seq 500: classified");
    p = mk(3000, 0, 0);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "confirmations of another session: classified");

    // Forward jump: 49..59 went to another edge.
    p = mk(1000, 60, 2);
    monitor_track(&p, &t);
    CHECK(t.jump && t.expected == 49 && t.first_new == 0 && !t.new_session,
          "jump 49->60 not detected (jump=%d expected=%lu)", t.jump, (unsigned long)t.expected);

    // After the jump the numbering restarts from 62.
    p = mk(1000, 62, 1);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "62 after 60+2: misclassified");

    // An old sample (already passed) is a duplicate, not a backward jump.
    p = mk(1000, 50, 1);
    monitor_track(&p, &t);
    CHECK(t.first_new == 1 && !t.jump, "seq 50 after 62: first_new %u", t.first_new);

    // Session change: no comparison with the previous numbering.
    p = mk(2000, 0, 1);
    monitor_track(&p, &t);
    CHECK(t.new_session && !t.jump && t.first_new == 0, "new session misclassified");
    p = mk(2000, 1, 1);
    monitor_track(&p, &t);
    CHECK(quiet(&t), "seq 1 of the new session misclassified");

    // session_id = 0 is a session like any other.
    p = mk(0, 5, 1);
    monitor_track(&p, &t);
    CHECK(t.new_session, "session 0 not recognised as new");
    p = mk(0, 5, 1);
    monitor_track(&p, &t);
    CHECK(t.first_new == 1, "duplicate in session 0: first_new %u", t.first_new);
}

// ---------------------------------------------------------------------------
// 7. Text values
// ---------------------------------------------------------------------------
static void test_fmt(void) {
    printf("[7] Uplink: text values for CSV and console\n");
    static const struct { uint16_t v; const char *u16, *batt, *alt; } C[] = {
        { 0,      "0",     "0.00",   "-10000" },
        { 1,      "1",     "0.01",   "-9999"  },
        { 98,     "98",    "0.98",   "-9902"  },
        { 142,    "142",   "1.42",   "-9858"  },
        { 4800,   "4800",  "48.00",  "-5200"  },
        { 8700,   "8700",  "87.00",  "-1300"  },
        { 10000,  "10000", "100.00", "0"      },
        { 10123,  "10123", "101.23", "123"    },
        { 32769,  "32769", "327.69", "22769"  },
        { 65280,  "65280", "652.80", "55280"  },
        { 65534,  "65534", "655.34", "55534"  },
        { 0xFFFF, "N/A",   "N/A",    "N/A"    },
    };
    char out[MONITOR_TXT_LEN];
    for (unsigned i = 0; i < sizeof(C) / sizeof(C[0]); i++) {
        monitor_fmt_u16(C[i].v, out);
        CHECK(strcmp(out, C[i].u16) == 0, "u16 %u -> '%s', expected '%s'", C[i].v, out, C[i].u16);
        monitor_fmt_batt(C[i].v, out);
        CHECK(strcmp(out, C[i].batt) == 0, "batt %u -> '%s', expected '%s'", C[i].v, out, C[i].batt);
        monitor_fmt_alt(C[i].v, out);
        CHECK(strcmp(out, C[i].alt) == 0, "alt %u -> '%s', expected '%s'", C[i].v, out, C[i].alt);
    }
}

int main(void) {
    test_alerts();
    test_alert_edges();
    test_ev_seq();
    test_parse();
    test_reject();
    test_track();
    test_fmt();

    if (failures) {
        printf("\n[KO] %d checks failed\n", failures);
        return 1;
    }
    printf("\n[OK] all v5 tests passed\n");
    return 0;
}
